  "cases": [
    {"id":"NREG-08","invariants":[{"index":0,"source_quotes":["If the applicant expresses a clear preference to add or remove space, either verbally or in writing, you may add or remove it per the applicant's preference."],"claim_ids":["E020"],"rationale":"Draft claim E020 faithfully captures the verbal or written disjunction as stated in the source text.","status":"pass"},{"index":1,"source_quotes":["If the applicant expresses a clear preference to add or remove space, either verbally or in writing, you may add or remove it per the applicant's preference."],"claim_ids":["E020"],"rationale":"Draft claim E020 preserves both alternatives to add or remove space according to applicant preference.","status":"pass"},{"index":2,"source_quotes":["you may add or remove it per the applicant's preference."],"claim_ids":["E020"],"rationale":"Draft claim E020 correctly uses permissive modality ('may') rather than an unconditional mandate.","status":"pass"},{"index":3,"source_quotes":["you may add or remove it per the applicant's preference."],"claim_ids":["E020"],"rationale":"Draft claim E020 sets the object as 'space' without silently assigning an unsupported referent.","status":"pass"}],"negative_controls":[{"index":0,"source_quotes":["If the applicant expresses a clear preference to add or remove space, either verbally or in writing, you may add or remove it per the applicant's preference."],"claim_ids":[],"rationale":"The negative control improperly imposes a mandatory requirement ('must') and restricts the medium to writing only, contradicting the source's explicit allowance of verbal expression and discretionary permission.","status":"pass"}],"uncertainty":""},{"id":"NREG-09","invariants":[{"index":0,"source_quotes":["If you receive applications from several family members, you should space the last names consistently, unless a family member expresses a clear preference for a different spacing."],"claim_ids":["E021"],"rationale":"Draft claim E021 accurately retains the recommendation ('should') for consistent family spacing conditioned on the absence of a contrary clear preference.","status":"pass"},{"index":1,"source_quotes":["For special-issuance passports, the spacing of an eligible family member's last name should match the spacing of the last name of the sponsor."],"claim_ids":["E022"],"rationale":"Draft claim E022 preserves the recommendation that spacing of an eligible family member's last name match the sponsor's spacing for special-issuance passports.","status":"pass"},{"index":2,"source_quotes":["unless a family member expresses a clear preference for a different spacing."],"claim_ids":["E021"],"rationale":"Draft claim E021 correctly places the clear preference exception on the family consistency recommendation rather than conflating it with the sponsor rule.","status":"pass"},{"index":3,"source_quotes":["NOTE: If you receive applications from several family members, you should space the last names consistently, unless a family member expresses a clear preference for a different spacing.\n\nNOTE: For special-issuance passports, the spacing of an eligible family member's last name should match the spacing of the last name of the sponsor."],"claim_ids":["E021","E022"],"rationale":"The draft maintains both notes separately without imposing an artificial hierarchy or mandatory force.","status":"pass"}],"negative_controls":[{"index":0,"source_quotes":["NOTE: If you receive applications from several family members, you should space the last names consistently, unless a family member expresses a clear preference for a different spacing.\n\nNOTE: For special-issuance passports, the spacing of an eligible family member's last name should match the spacing of the last name of the sponsor."],"claim_ids":[],"rationale":"The negative control invents a universal 'must' rule and wrongly overrides preference across all family members, ignoring the separate recommendation scopes in the source.","status":"pass"}],"uncertainty":""},{"id":"NREG-10","invariants":[{"index":0,"source_quotes":["Name spacing issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).","Name suffix issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2)."],"claim_ids":[],"rationale":"Neither draft contains claims extracting the separate rewrite rules for spacing (8 FAM 403.1-3(B)(b)) and suffix issues (8 FAM 403.1-3(B)(e)).","status":"fail"},{"index":1,"source_quotes":["Name spacing issues are generally not sufficient cause to rewrite a passport","Name suffix issues are generally not sufficient cause to rewrite a passport"],"claim_ids":[],"rationale":"The draft omitted these provisions entirely, failing to represent the qualified non-absolute standard ('generally not sufficient').","status":"fail"},{"index":2,"source_quotes":["unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2)."],"claim_ids":[],"rationale":"The draft lacks extracted claims capturing the Department disregard exception.","status":"fail"},{"index":3,"source_quotes":["unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2)."],"claim_ids":[],"rationale":"Because the rewrite rules were not extracted, the draft fails to articulate the exception or preserve its non-mandatory status.","status":"fail"},{"index":4,"source_quotes":["(see 8 FAM 1001.2)"],"claim_ids":[],"rationale":"The cross-reference to 8 FAM 1001.2 for passport rewrites is absent from the drafted claims.","status":"fail"}],"negative_controls":[{"index":0,"source_quotes":["Name spacing issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).","Name suffix issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2)."],"claim_ids":[],"rationale":"The negative control posits an absolute prohibition ('must never') and ignores the express exception where the Department disregarded a clear preference.","status":"pass"},{"index":1,"source_quotes":["Name spacing issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2)."],"claim_ids":[],"rationale":"The negative control creates an absolute affirmative requirement ('must rewrite every passport') where the source merely qualifies an insufficiency rule with an exception and cross-reference.","status":"pass"}],"uncertainty":""},{"id":"NREG-11","invariants":[{"index":0,"source_quotes":["under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"],"claim_ids":["N005"],"rationale":"Draft claim N005 accurately reflects the possible requirement of identity evidence under 22 CFR 51.23(c) in accordance with Department guidance.","status":"pass"},{"index":1,"source_quotes":["to establish the name that best identifies the applicant:"],"claim_ids":["N005"],"rationale":"Draft claim N005 preserves the purpose phrase explicitly in its scope and summary fields.","status":"pass"},{"index":2,"source_quotes":["The applicant generally will need the name change documentation to change the name on her/his ID."],"claim_ids":["N008"],"rationale":"The draft notes the qualified practical guidance in the context quotes of N008, although it is not formalized as its own standalone claim.","status":"pass"},{"index":3,"source_quotes":["under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"],"claim_ids":["N005","N006","N009"],"rationale":"Draft claim N005 preserves 'possible' modality ('might be required') without converting it into a universal duty, while N009 retains the explicit exemption for applicants who changed names within one year.","status":"pass"}],"negative_controls":[{"index":0,"source_quotes":["under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:","Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."],"claim_ids":[],"rationale":"The negative control erroneously universalizes an ID submission duty ('All applicants must submit ID') when the source uses 'might be required' and explicitly exempts applicants who changed names within one year.","status":"pass"}],"uncertainty":""},{"id":"NREG-12","invariants":[{"index":0,"source_quotes":["If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."],"claim_ids":["N006","E005"],"rationale":"Draft claims N006 and E005 correctly distinguish the applicant's material name change from the DS-11 application form context.","status":"pass"},{"index":1,"source_quotes":["If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."],"claim_ids":["N006","E005"],"rationale":"Neither claim mispairs the action 'has had a material name change' with 'form DS-11' as its direct object.","status":"pass"},{"index":2,"source_quotes":["If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."],"claim_ids":["N006","E005"],"rationale":"The claims retain the full conditional logic and scope rather than forcing synthetic sub-predicates.","status":"pass"},{"index":3,"source_quotes":["If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."],"claim_ids":["N006","E005"],"rationale":"Both claims appropriately identify the required action as suspending the application to request acceptable ID, without mandating the filing of form DS-11.","status":"pass"}],"negative_controls":[],"uncertainty":""},{"id":"NREG-13","invariants":[{"index":0,"source_quotes":["The term “applicant” is used hereinafter for the individual whose citizenship and identity is being adjudicated, including for form DS-2060."],"claim_ids":[],"rationale":"The draft excerpts and claims in draft run names-excerpts-03 omit the definition of 'applicant' and its explicit reference to form DS-2060, extracting only minor applicants in E000.","status":"fail"},{"index":1,"source_quotes":["For purposes of this chapter, minor applicants are defined as un-emancipated applicants under the age of 18."],"claim_ids":["E000"],"rationale":"Draft claim E000 defines minor applicants as un-emancipated applicants under the age of 18 scoped to this chapter.","status":"pass"},{"index":2,"source_quotes":["For purposes of this chapter, minor applicants are defined as un-emancipated applicants under the age of 18."],"claim_ids":["E000"],"rationale":"Claim E000 correctly retains the emancipation element ('un-emancipated'), the age restriction ('under the age of 18'), and chapter limitation.","status":"pass"},{"index":3,"source_quotes":["For purposes of this chapter, minor applicants are defined as un-emancipated applicants under the age of 18."],"claim_ids":["E000"],"rationale":"Claim E000 correctly leaves the actor blank without inventing an artificial duty bearer for the definitional statement.","status":"pass"}],"negative_controls":[{"index":0,"source_quotes":["For purposes of this chapter, minor applicants are defined as un-emancipated applicants under the age of 18."],"claim_ids":[],"rationale":"The negative control overgeneralizes the scope across 'every passport-related context' and omits the crucial condition of being un-emancipated.","status":"pass"}],"uncertainty":""},{"id":"NREG-14","invariants":[{"index":0,"source_quotes":["Arabic ordinal numbers must be changed to Roman numerals, for example, 2nd to II, 3rd to III:"],"claim_ids":["E023"],"rationale":"Claim E023 captures the conversion of Arabic ordinal numbers to Roman numerals with the illustrative examples.","status":"pass"},{"index":1,"source_quotes":["Arabic ordinal numbers must be changed to Roman numerals, for example, 2nd to II, 3rd to III:"],"claim_ids":["E023"],"rationale":"Draft claim E023 isolates the ordinal number conversion rule to Section 8 FAM 403.1-5(B)(c) without conflating it with Name Spacing.","status":"pass"},{"index":2,"source_quotes":["Some applicants may include the prefix “Sr.” as an abbreviation for “Señor” in Spanish meaning “Mr.” or “Mister” in English."],"claim_ids":[],"rationale":"The draft completely omitted paragraph (d) concerning the prefix 'Sr.' meaning 'Señor' and ranks/titles guidance.","status":"fail"},{"index":3,"source_quotes":["If you determine that this is the case, follow the guidance in 8 FAM 403.1-5(C) regarding ranks and titles."],"claim_ids":[],"rationale":"No draft claim captures the conditional instruction to follow 8 FAM 403.1-5(C) regarding ranks and titles.","status":"fail"},{"index":4,"source_quotes":["If you determine that this is the case, follow the guidance in 8 FAM 403.1-5(C) regarding ranks and titles."],"claim_ids":[],"rationale":"The guidance is entirely omitted from the draft claims, leaving any rule regarding handling or removal unrepresented.","status":"fail"}],"negative_controls":[],"uncertainty":""}
  ]
}
